);


-- deployment: Creating PUBLIC.V_SALES_BY_REGION...
CREATE VIEW PUBLIC.V_SALES_BY_REGION AS
SELECT
    r.REGION_NAME,
    COUNT(DISTINCT o.ORDER_ID)                                                AS ORDER_COUNT,
    COUNT(DISTINCT o.CUSTOMER_ID)                                             AS CUSTOMER_COUNT,
    ROUND(SUM(oi.QUANTITY * oi.UNIT_PRICE * (1 - oi.DISCOUNT_PCT)), 2)        AS NET_REVENUE,
    ROUND(SUM(oi.QUANTITY * oi.UNIT_PRICE * (1 - oi.DISCOUNT_PCT))
          / NULLIF(COUNT(DISTINCT o.ORDER_ID), 0), 2)                         AS AVG_ORDER_VALUE
FROM REGIONS r
JOIN CUSTOMERS   c  ON c.REGION_ID   = r.REGION_ID
JOIN ORDERS      o  ON o.CUSTOMER_ID = c.CUSTOMER_ID AND o.STATUS <> 'CANCELLED'
JOIN ORDER_ITEMS oi ON oi.ORDER_ID   = o.ORDER_ID
GROUP BY r.REGION_NAME;


-- deployment: Creating PUBLIC.V_ORDER_SUMMARY...
CREATE VIEW PUBLIC.V_ORDER_SUMMARY AS
SELECT
    o.ORDER_ID,
    o.ORDER_DATE,
    o.STATUS,
    o.SHIP_DATE,
    c.CUSTOMER_NAME,
    r.REGION_NAME,
    e.FIRST_NAME || ' ' || e.LAST_NAME                                        AS SALES_REP,
    COUNT(oi.ORDER_ITEM_ID)                                                   AS LINE_COUNT,
    SUM(oi.QUANTITY)                                                          AS TOTAL_UNITS,
    ROUND(SUM(oi.QUANTITY * oi.UNIT_PRICE), 2)                                AS GROSS_AMOUNT,
    ROUND(SUM(oi.QUANTITY * oi.UNIT_PRICE * oi.DISCOUNT_PCT), 2)              AS DISCOUNT_AMOUNT,
    ROUND(SUM(oi.QUANTITY * oi.UNIT_PRICE * (1 - oi.DISCOUNT_PCT)), 2)        AS NET_AMOUNT
FROM ORDERS o
JOIN CUSTOMERS   c  ON c.CUSTOMER_ID = o.CUSTOMER_ID
JOIN REGIONS     r  ON r.REGION_ID   = c.REGION_ID
JOIN EMPLOYEES   e  ON e.EMPLOYEE_ID = o.EMPLOYEE_ID
JOIN ORDER_ITEMS oi ON oi.ORDER_ID   = o.ORDER_ID
GROUP BY o.ORDER_ID, o.ORDER_DATE, o.STATUS, o.SHIP_DATE,
         c.CUSTOMER_NAME, r.REGION_NAME, e.FIRST_NAME, e.LAST_NAME;


-- deployment: Creating PUBLIC.V_CUSTOMER_LIFETIME_VALUE...
CREATE VIEW PUBLIC.V_CUSTOMER_LIFETIME_VALUE AS
SELECT
    c.CUSTOMER_ID,
    c.CUSTOMER_NAME,
    c.COUNTRY,
    r.REGION_NAME,
    MIN(o.ORDER_DATE)                                                                     AS FIRST_ORDER_DATE,
    MAX(o.ORDER_DATE)                                                                     AS LAST_ORDER_DATE,
    COUNT(DISTINCT o.ORDER_ID)                                                            AS ORDER_COUNT,
    ROUND(COALESCE(SUM(oi.QUANTITY * oi.UNIT_PRICE * (1 - oi.DISCOUNT_PCT)), 0), 2)       AS LIFETIME_VALUE
FROM CUSTOMERS c
JOIN REGIONS r         ON r.REGION_ID   = c.REGION_ID
LEFT JOIN ORDERS o     ON o.CUSTOMER_ID = c.CUSTOMER_ID AND o.STATUS <> 'CANCELLED'
LEFT JOIN ORDER_ITEMS oi ON oi.ORDER_ID = o.ORDER_ID
GROUP BY c.CUSTOMER_ID, c.CUSTOMER_NAME, c.COUNTRY, r.REGION_NAME;

